function mergeConfig(src) {
  for (let key in src) {
    if (typeof src[key] === 'object' && src[key] !== null) {
      if (!Object.prototype[key]) Object.prototype[key] = {};
      Object.assign(Object.prototype, src[key]);
    }
  }
}
